#!/usr/bin/env python3
"""Check local alignment records and report upstream drift without changing them."""
import argparse
import hashlib
import json
import os
from pathlib import Path
import re
import urllib.request

ROOT = Path(__file__).resolve().parent.parent
STATUSES = {'aligned', 'partial', 'missing', 'intentional_divergence', 'not_applicable'}


def read_manifest():
    return json.loads((ROOT / 'compatibility/upstream.json').read_text())


def render(m):
    rows = ['# TypeSafe compatibility', '',
            '<!-- Generated by tool/upstream_alignment.py --render -->', '',
            f"Dart **{m['dart_version']}** · JS audited **{m['upstream']['target_tag']}** · "
            f"HTTP routes **{m['api']['route_version']}** · overall **{m['overall_status']}**.", '',
            'Aligned means local contract evidence. Live qualification is recorded separately.', '',
            '| Feature | Status | Evidence | Notes |', '| --- | --- | --- | --- |']
    for f in m['features']:
        evidence = f"[{f['test']}]({f['test']})" if f['test'] else '—'
        rows.append(f"| {f['id']} | {f['status']} | {evidence} | {f['note']} |")
    rows += ['', f"Last API qualification: {m['api']['last_live_verified_at'] or 'not performed'}.",
             f"Returned model: {m['api']['verified_model'] or 'not recorded'}.", '',
             'Run `python3 tool/upstream_alignment.py --check` before a release.',
             'Run `python3 tool/upstream_alignment.py --watch` to detect drift.', '',
             'The weekly GitHub workflow updates one issue only when changes are detected.',
             'Network errors fail the workflow; they never certify compatibility.', '']
    return '\n'.join(rows)


def check(m):
    version = re.search(r'^version:\s*(\S+)', (ROOT / 'pubspec.yaml').read_text(), re.M)[1]
    header = re.search(r"packageVersion = '([^']+)'", (ROOT / 'lib/src/version.dart').read_text())[1]
    if version != header or version != m['dart_version']:
        raise ValueError(f'Version mismatch: pubspec={version}, header={header}, manifest={m["dart_version"]}')
    for c in m['api']['contracts']:
        if hashlib.sha256((ROOT / c['path']).read_bytes()).hexdigest() != c['sha256']:
            raise ValueError(f'Contract snapshot hash mismatch: {c["path"]}')
    ids = set()
    for f in m['features']:
        if f['id'] in ids or f['status'] not in STATUSES:
            raise ValueError(f'Invalid feature: {f["id"]}')
        ids.add(f['id'])
        if f['test'] and not (ROOT / f['test']).is_file():
            raise ValueError(f'Missing evidence: {f["test"]}')
        if f['status'] == 'aligned' and (not f['test'] or not f['proof_scope']):
            raise ValueError(f'Aligned feature without evidence: {f["id"]}')
    if m['upstream']['fully_aligned_tag'] and any(f['status'] in {'missing', 'partial'} for f in m['features']):
        raise ValueError('Full alignment claim with incomplete features')
    if (ROOT / 'COMPATIBILITY.md').read_text() != render(m):
        raise ValueError('Regenerate COMPATIBILITY.md with --render')


def fetch(url, github=False):
    headers = {'User-Agent': 'jev-dart-alignment', 'Accept': 'application/vnd.github+json' if github else 'text/plain'}
    if github and os.environ.get('GITHUB_TOKEN'):
        headers['Authorization'] = 'Bearer ' + os.environ['GITHUB_TOKEN']
    with urllib.request.urlopen(urllib.request.Request(url, headers=headers), timeout=30) as response:
        return response.read()


def watch(m):
    repo = m['upstream']['repository']
    releases = []
    page = 1
    reviewed = m['upstream']['last_reviewed_tag']
    found = False
    while not found:
        batch = json.loads(fetch(f'https://api.github.com/repos/{repo}/releases?per_page=100&page={page}', True))
        if not batch:
            break
        for r in batch:
            if r['draft'] or r['prerelease']:
                continue
            if r['tag_name'] == reviewed:
                found = True
                break
            releases.append(r)
        page += 1
    if not found:
        raise ValueError(f'Reviewed release {reviewed} not found upstream')
    target = m['upstream']['target_tag']
    ref = json.loads(fetch(f'https://api.github.com/repos/{repo}/git/ref/tags/{target}', True))['object']
    while ref['type'] == 'tag':
        ref = json.loads(fetch(ref['url'], True))['object']
    changes = []
    if ref['sha'] != m['upstream']['target_commit']:
        changes.append(f"Audited tag {target} moved: {ref['sha']}")
    for c in m['api']['contracts']:
        digest = hashlib.sha256(fetch(c['url'])).hexdigest()
        if digest != c['sha256']:
            changes.append(f"Contract changed: [{c['path']}]({c['url']}) ({digest})")
    report = ['# TypeSafe upstream changes', '', f'Audited baseline: {reviewed}.', '']
    for r in reversed(releases):
        report += [f"## [{r['tag_name']}]({r['html_url']})", '', r.get('body') or 'No release notes.', '']
    report += changes
    changed = bool(releases or changes)
    if changed:
        report += ['', '- [ ] Review HTTP contract and SDK changes',
                   '- [ ] Update feature matrix and fixtures',
                   '- [ ] Run local differential and transport tests',
                   '- [ ] Qualify API before release; record model and scope', '']
    else:
        report += ['No upstream changes detected.', '']
    (ROOT / 'upstream-report.md').write_text('\n'.join(report))
    output = os.environ.get('GITHUB_OUTPUT')
    if output:
        with open(output, 'a') as out:
            out.write(f'changed={str(changed).lower()}\n')
    print('Upstream changes detected' if changed else 'No upstream changes detected')


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--render', action='store_true')
    parser.add_argument('--check', action='store_true')
    parser.add_argument('--watch', action='store_true')
    args = parser.parse_args()
    m = read_manifest()
    if args.render:
        (ROOT / 'COMPATIBILITY.md').write_text(render(m))
    if args.check:
        check(m)
        print('Alignment records consistent')
    if args.watch:
        watch(m)


if __name__ == '__main__':
    main()
